import{c as a,Q as i,j as n,m as t}from"./chunks/framework.BXc4yaFE.js";const v=JSON.parse('{"title":"Beyond Individual Intelligence: Surveying Collaboration, Failure Attribution, and Self-Evolution in LLM-based Multi-Agent Systems","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.14892","title":"Beyond Individual Intelligence: Surveying Collaboration, Failure Attribution, and Self-Evolution in LLM-based Multi-Agent Systems","arxiv_id":2605.14892,"collected_at":"2026-08-04T00:00:00.000Z","collected_by":"routine-d","domain":"Multi-Agent","pdf_path":"pdfs/2605.14892.pdf","year":2026},"headers":[],"relativePath":"research/papers/2026-08-04-beyond-individual-intelligence-survey-mas-collaboration-failure-self-evolution-2605-14892.md","filePath":"research/papers/2026-08-04-beyond-individual-intelligence-survey-mas-collaboration-failure-self-evolution-2605-14892.md","lastUpdated":1785909234000}'),l={name:"research/papers/2026-08-04-beyond-individual-intelligence-survey-mas-collaboration-failure-self-evolution-2605-14892.md"};function o(r,e,s,d,u,c){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="beyond-individual-intelligence-surveying-collaboration-failure-attribution-and-self-evolution-in-llm-based-multi-agent-systems" tabindex="-1">Beyond Individual Intelligence: Surveying Collaboration, Failure Attribution, and Self-Evolution in LLM-based Multi-Agent Systems <a class="header-anchor" href="#beyond-individual-intelligence-surveying-collaboration-failure-attribution-and-self-evolution-in-llm-based-multi-agent-systems" aria-label="Permalink to &quot;Beyond Individual Intelligence: Surveying Collaboration, Failure Attribution, and Self-Evolution in LLM-based Multi-Agent Systems&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本篇調查 LLM-based 自主 agent 如何更有效協作。單一 agent 在推理與規劃上表現不錯，但面對需要持續協調的複雜任務仍力有未逮。作者提出 LIFE 遞進框架，涵蓋四個相互關聯階段：建立基礎能力、促成 agent 協作、透過歸因診斷失敗、達成自主改善。論文強調失敗如何在多代理系統中傳播，並主張發展閉環系統，能持續辨識問題、重組自身、精煉行為，朝向更具自組織性的集體智能形式演進。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>「失敗歸因（failure attribution）」與「閉環自主改善」的分期框架，直接對應 workspace dreaming-consolidator（跨 session 記憶固化萃取 playbook）與 self-escalate（收斂判斷）的設計動機——LIFE 框架可作為未來評估這兩個機制是否涵蓋「歸因→重組→精煉」完整閉環的外部參照基準。</p>',5)])])}const f=a(l,[["render",o]]);export{v as __pageData,f as default};
